from collections import deque
from softlock_detector import SPEC, State, successors
start = State(SPEC["start_location"], frozenset(), frozenset())
forward = {start: []}
q = deque([start])
while q:
    s = q.popleft()
    for t in successors(s, SPEC):
        forward[s].append(t)
        if t not in forward:
            forward[t] = []; q.append(t)
target = State("fork", frozenset(), frozenset({"decoy_door"}))
print("target in forward:", target in forward)
winners = {s for s in forward if s.location == SPEC["win_location"]}
backward = {s: [] for s in forward}
for s, ts in forward.items():
    for t in ts:
        backward[t].append(s)
can_win = set()
q = deque(winners)
while q:
    s = q.popleft()
    if s in can_win: continue
    can_win.add(s); q.extend(backward[s])
print("target in can_win:", target in can_win)
print("softlocks:", sorted((forward.keys() - can_win), key=str))
EOF')

