from collections import deque
from softlock_detector import SPEC, State, successors
start = State(SPEC["start_location"], frozenset(), frozenset())
forward = {start: []}
q = deque([start])
while q:
    s = q.popleft()
    for t in successors(s, SPEC):
        forward[s].append(t)
        if t not in forward:
            forward[t] = []; q.append(t)
target = State("fork", frozenset(), frozenset({"decoy_door"}))
print("successors recorded for target:", forward.get(target))
# find all states s where target appears as successor
preds = [s for s, ts in forward.items() if any(t == target for t in ts)]
print("predecessors:", preds)
# how does can_win reach target? BFS backwards from winners printing path
winners = [s for s in forward if s.location == SPEC["win_location"]]
parent = {}
seen = set(winners)
q = deque(winners)
while q:
    s = q.popleft()
    for p in [x for x, ts in forward.items() if s in ts]:
        if p not in seen:
            seen.add(p); parent[p] = s; q.append(p)
print("target seen:", target in seen)
if target in seen:
    cur, path = target, []
    while cur in parent:
        path.append(cur); cur = parent[cur]
    path.append(cur)
    for x in reversed(path):
        print(" ", x.location, sorted(x.inventory), sorted(x.open_doors))
EOF')
